import {predict as modelPredict} from './training.mjs?v=20261101-eval1';
import {finite} from '../agent/core.mjs';
export const FORECAST_IDS=new Set(['arps','crm','tcn','lstm','boost','forest','xgboost']);
export const FORECAST_ASSUMPTION='固定已训练模型；未来注入量、压力及含水率保持最新观测水平，产油递归预测，油水量按恒定含水率换算；不代表已实施调控效果。';
function quantile(a,p){if(!a.length)return null;const sorted=[...a].sort((a,b)=>a-b),i=(sorted.length-1)*p,j=Math.floor(i);return sorted[j]+(sorted[Math.min(j+1,sorted.length-1)]-sorted[j])*(i-j);}
export async function forecast(m,fit,history,{days=7,well,remote,predict=modelPredict,residuals=[]}={}){if(!FORECAST_IDS.has(m.id))throw Error('该模型不支持日产油/产液未来外推，请查看计算输入结果');if(!Number.isInteger(days)||days<1||days>60)throw Error('预测天数需为1–60整数');const ids=[...new Set(history.map(r=>r.well_id))].filter(w=>!well||well==='all'||w===well);if(!ids.length)throw Error('没有所选井的历史资料');const q025=quantile(residuals.filter(finite),.025),q975=quantile(residuals.filter(finite),.975),rows=[],warnings=[],start=performance.now();for(const id of ids){let past=history.filter(r=>r.well_id===id).sort((a,b)=>String(a.date).localeCompare(String(b.date))).map(r=>({...r}));past=[...new Map(past.map(r=>[r.date,r])).values()];if(!past.length)continue;const last=past.at(-1);if(!Number.isFinite(Date.parse(last.date)))throw Error('历史日期无效：'+id);try{for(let d=1;d<=days;d++){const previous=past.at(-1),date=new Date(Date.parse(previous.date)+86400000).toISOString().slice(0,10),next={...previous,date};const window=past.slice(-16),batch=m.id==='arps'?[next]:m.id==='crm'?[...past,next]:m.id==='tcn'?[...window,next]:[next];const out=await predict(m,fit,batch,window,remote),prediction=out.findLast(r=>r.well_id===id&&r.date===date)?.prediction;if(!finite(prediction))throw Error('该井参数或连续窗口未覆盖');const value=Math.max(0,Number(prediction)),wc=finite(previous.water_cut)?Number(previous.water_cut)/100:null;if(m.target==='liquid'){next.liquid=value;if(wc!==null&&wc>=0&&wc<1){next.oil=value*(1-wc);next.water=value*wc;}}else{next.oil=value;if(wc!==null&&wc>=0&&wc<1){next.liquid=value/(1-wc);next.water=next.liquid-value;}}past.push(next);rows.push({well_id:id,date,horizon:d,actual:null,prediction:value,lower:q975===null?null:Math.max(0,value-q975),upper:q025===null?null:Math.max(0,value-q025),target:m.target,unit:m.unit,baseline_date:last.date,assumptions:FORECAST_ASSUMPTION});}}catch(e){warnings.push(id+'：'+e.message);}}if(!rows.length)throw Error('未能生成未来结果：'+warnings.join('；'));return {rows,warnings,duration:(performance.now()-start)/1000,assumptions:FORECAST_ASSUMPTION,referenceBand:residuals.length?'固定验证残差2.5%–97.5%参考带；未校准覆盖率，不是置信区间':'无验证残差，不绘制误差参考带'};}
export const canChangeForecastSelection=s=>!s.busy;

export function applyForecastSelection(s,well){if(!canChangeForecastSelection(s))return false;s.forecastWell=well;s.forecast=null;return true;}
